function Actions({edit,remove}:{edit:()=>void;remove:()=>void}){return <div className="row-actions"><button onClick={edit} aria-label="Editar"><Pencil/></button><button className="danger" onClick={remove} aria-label="Excluir"><Trash2/></button></div>}
function Empty({text}:{text:string}){return <div className="operations-empty"><Boxes/><strong>{text}</strong></div>}

function Editor({catalog,editing,busy,close,save,bikes,stock,technicians}:{catalog:SaleCatalog;editing:Editing;busy:boolean;close:()=>void;save:(event:React.FormEvent<HTMLFormElement>)=>void;bikes:BikeItem[];stock:StockItem[];technicians:string[]}){return <Dialog open={!!editing} onOpenChange={open=>{if(!open&&!busy)close()}}><DialogContent className={'edit-dialog '+(editing?.entity==='sale'?'sale-edit-dialog':'')}><DialogTitle>{editing?.entity==='sale'?(editing.item.version===0?'Nova venda':'Editar venda'):editing?.item.id.match(/[0-9a-f-]{36}$/)?'Novo registro':'Editar registro'}</DialogTitle><DialogDescription>{editing?.entity==='sale'?'Preencha a venda. Abra as opções abaixo apenas quando precisar.':'Revise as informações e salve para atualizar o painel.'}</DialogDescription>{editing&&<form onSubmit={save} key={editing.item.id}><Fields catalog={catalog} editing={editing} bikes={bikes} stock={stock} technicians={technicians}/><div className="form-actions"><button type="button" className="secondary" onClick={close} disabled={busy}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Salvando…':'Salvar'}</button></div></form>}</DialogContent></Dialog>}
function Fields({catalog,editing,bikes,stock,technicians}:{catalog:SaleCatalog;editing:Exclude<Editing,null>;bikes:BikeItem[];stock:StockItem[];technicians:string[]}){const item=editing.item;
 if(editing.entity==='price'){const value=item as PriceItem;return <><label>Produto<input name="product" required maxLength={300} defaultValue={value.product}/></label><label>Tipo<select name="kind" defaultValue={value.kind}><option>Revenda</option><option>Custo</option></select></label><label>Fornecedor<input name="supplier" maxLength={200} defaultValue={value.supplier}/></label><label>Valor (R$)<input type="number" name="price" min="0" step="0.01" max="999999999" defaultValue={value.price===null?'':value.price/100}/></label></>}
 if(editing.entity==='sale')return <SaleFields value={item as SaleItem} catalog={catalog}/>;
 if(editing.entity==='academyInvoice'){const value=item as AcademyInvoice;return <><div className="form-grid"><label>Competência<input type="month" name="period" required defaultValue={value.period}/></label><label>Vencimento<input type="date" name="dueDate" defaultValue={value.dueDate}/></label><label>Valor (R$)<input type="number" min="0" step="0.01" name="amount" required defaultValue={value.amount===null?'':value.amount/100}/></label><label>Situação<select name="status" defaultValue={value.status}><option value="paid">Pago</option><option value="pending">A pagar</option><option value="review">Conferir</option></select></label></div><label>Identificação do boleto<input name="label" required defaultValue={value.label}/></label></>}
 if(editing.entity==='expenseTechnician'){const value=item as ExpenseTechnician;return <label>Nome do técnico<input name="name" required maxLength={200} defaultValue={value.name}/></label>}
 if(editing.entity==='stockMovement'){const value=item as StockMovement;return <><div className="form-grid"><label>Data<input type="date" name="date" required defaultValue={value.date}/></label><label>Produto<select name="productId" required defaultValue={value.productId}><option value="">Selecione</option>{stock.map(entry=><option value={entry.id} key={entry.id}>{entry.product}</option>)}</select></label><label>Técnico<input name="technician" list="technicians" required defaultValue={value.technician}/><datalist id="technicians">{technicians.map(name=><option key={name}>{name}</option>)}</datalist></label><label>Quantidade<input type="number" min="0.01" step="0.01" name="quantity" required defaultValue={value.quantity}/></label></div><label>Observação<input name="notes" defaultValue={value.notes}/></label></>}
 if(editing.entity==='fuel'){const value=item as FuelItem;return <div className="form-grid"><label>Data<input type="date" name="date" required defaultValue={value.date}/></label><label>Técnico<input name="technician" required defaultValue={value.technician}/></label><label>Placa<input name="plate" defaultValue={value.plate}/></label><label>Valor (R$)<input type="number" step="0.01" name="amount" required defaultValue={value.amount===null?'':value.amount/100}/></label></div>}
 if(editing.entity==='oil'){const value=item as OilItem;return <><div className="form-grid"><label>Data da conferência<input type="date" name="date" required defaultValue={value.date}/></label><label>Técnico<input name="technician" required defaultValue={value.technician}/></label><label>Placa<input name="plate" defaultValue={value.plate}/></label><label>Valor (R$)<input type="number" step="0.01" name="amount" defaultValue={value.amount===null?'':value.amount/100}/></label><label>Quilometragem<input type="number" name="odometer" defaultValue={value.odometer??''}/></label><label>Última troca<input type="date" name="lastChange" defaultValue={value.lastChange}/></label></div><label>Observações<input name="notes" defaultValue={value.notes}/></label></>}
 if(editing.entity==='stock'){const value=item as StockItem;return <><label>Produto<input name="product" required defaultValue={value.product}/></label><div className="form-grid"><label>Estoque inicial<input type="number" step="0.01" name="initial" defaultValue={value.initial}/></label><label>Entradas acumuladas<input type="number" step="0.01" name="incoming" defaultValue={value.incoming}/></label><label>Saídas acumuladas<input type="number" step="0.01" name="outgoing" defaultValue={value.outgoing}/></label><label>Estoque mínimo<input type="number" step="0.01" name="minimum" defaultValue={value.minimum}/></label></div></>}
 if(editing.entity==='bike'){const value=item as BikeItem;return <><div className="form-grid"><label>Placa<input name="plate" required defaultValue={value.plate}/></label><label>Vencimento<input type="date" name="dueDate" defaultValue={value.dueDate}/></label><label>Motorista<input name="driver" defaultValue={value.driver}/></label><label>Proprietário<input name="owner" defaultValue={value.owner}/></label></div><label>Licenciamento / IPVA<input name="licensing" defaultValue={value.licensing}/></label></>}
 if(editing.entity==='payroll'){const value=item as PayrollItem,moneyInput=(name:string,label:string,amount:number)=><label>{label}<input type="number" min="0" step="0.01" name={name} defaultValue={amount/100}/></label>;return <><div className="form-grid"><label>Funcionário<input name="employee" required defaultValue={value.employee}/></label><label>Competência<input type="month" name="period" required defaultValue={value.period}/></label>{moneyInput('baseSalary','Salário base',value.baseSalary)}{moneyInput('hazardPay','Periculosidade',value.hazardPay)}{moneyInput('overtime','Horas extras',value.overtime)}{moneyInput('bonus','Bônus',value.bonus)}{moneyInput('inss','INSS',value.inss)}{moneyInput('absences','Atrasos / faltas',value.absences)}{moneyInput('advance','Adiantamento',value.advance)}{moneyInput('loan','Empréstimo',value.loan)}{moneyInput('fines','Multas',value.fines)}{moneyInput('advance15','Adiantamento dia 15',value.advance15)}</div><label>Observações<input name="notes" maxLength={1000} defaultValue={value.notes}/></label></>}
 if(editing.entity==='process'){const value=item as ProcessItem;return <><label>Nome do processo<input name="title" required maxLength={300} defaultValue={value.title} placeholder="Ex.: Instalação da piscina do cliente"/></label><div className="form-grid"><label>Cliente / projeto<input name="client" maxLength={200} defaultValue={value.client}/></label><label>Área<input name="area" maxLength={100} defaultValue={value.area} placeholder="Operação, Comercial..."/></label><label>Responsável<input name="owner" list="technicians" maxLength={200} defaultValue={value.owner}/></label><label>Prazo<input type="date" name="dueDate" defaultValue={value.dueDate}/></label><label>Etapa<select name="status" defaultValue={value.status}>{processStatuses.map(([status,text])=><option value={status} key={status}>{text}</option>)}</select></label><label>Prioridade<select name="priority" defaultValue={value.priority}><option value="low">Baixa</option><option value="medium">Média</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></label><label>Horas previstas<input type="number" min="0" step="0.5" name="estimatedHours" defaultValue={value.estimatedMinutes/60}/></label><label>Horas realizadas<input type="number" min="0" step="0.5" name="trackedHours" defaultValue={value.trackedMinutes/60}/></label><label>Receita prevista (R$)<input type="number" min="0" step="0.01" name="revenue" defaultValue={value.revenue/100}/></label><label>Custo previsto (R$)<input type="number" min="0" step="0.01" name="cost" defaultValue={value.cost/100}/></label></div><label>Descrição / próximos passos<textarea name="notes" rows={4} maxLength={2000} defaultValue={value.notes}/></label></>}
 const value=item as MaintenanceItem;return <div className="form-grid"><label>Placa<select name="plate" defaultValue={value.plate}>{bikes.map(entry=><option key={entry.id}>{entry.plate}</option>)}</select></label><label>Data<input type="date" name="date" required defaultValue={value.date}/></label><label>Serviço<input name="service" required defaultValue={value.service}/></label><label>Oficina<input name="shop" defaultValue={value.shop}/></label><label>Motorista<input name="driver" defaultValue={value.driver}/></label><label>Valor (R$)<input type="number" step="0.01" name="amount" defaultValue={value.amount===null?'':value.amount/100}/></label></div>}
